public class ShipmentNotifierTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static class CapturingLog implements EventLog {
        final java.util.List<String> lines = new java.util.ArrayList<>();

        public void record(String message) {
            lines.add(message);
        }
    }

    public static void main(String[] args) {
        CapturingLog log = new CapturingLog();
        ShipmentNotifier notifier = new ShipmentNotifier(log);
        check("constructor records nothing", 0, log.lines.size());

        notifier.ship("A-1");
        check("log after ship", "[SHIPPED A-1]", log.lines.toString());
        check("shippedCount after one ship", 1, notifier.shippedCount());

        notifier.delay("A-2", 3);
        check("log after delay", "[SHIPPED A-1, DELAYED A-2 by 3 day(s)]", log.lines.toString());

        notifier.delay("A-3", 0);
        check("delay of 0 days records nothing", 2, log.lines.size());
        check("delay of 0 days is not counted", 1, notifier.delayedCount());

        check("summary text", "shipped=1 delayed=1", notifier.summary());

        ShipmentNotifier second = new ShipmentNotifier(log);
        second.ship("B-9");
        check("two notifiers share one injected log", 3, log.lines.size());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

