/**
 * TASK: Complete ShipmentNotifier. The EventLog interface above it is
 * provided -- do not change it.
 *
 * ShipmentNotifier does not create a log of its own and never prints.
 * It is HANDED an EventLog through its constructor (constructor injection)
 * and delegates every message to it, so a test can pass in a fake log and
 * read back exactly what was recorded.
 *
 * Rules:
 *   - ship(orderId)        records "SHIPPED " + orderId and counts a shipment
 *   - delay(orderId, days) records "DELAYED " + orderId + " by " + days + " day(s)"
 *                          and counts a delay, but ONLY when days > 0;
 *                          days <= 0 records nothing and counts nothing
 *   - summary()            returns "shipped=1 delayed=1" (no log entry)
 *   - the constructor itself must not record anything
 *
 * Example: ship("A-1") then delay("A-2", 3) leaves the log holding
 *   ["SHIPPED A-1", "DELAYED A-2 by 3 day(s)"] and summary() "shipped=1 delayed=1".
 */
interface EventLog {

    void record(String message);
}

public class ShipmentNotifier {

    private final EventLog log;
    private int shipped = 0;
    private int delayed = 0;

    public ShipmentNotifier(EventLog log) {
        this.log = log;
    }

    public void ship(String orderId) {
        shipped++;
        log.record("SHIPPED " + orderId);
    }

    public void delay(String orderId, int days) {
        if (days <= 0) {
            return;
        }
        delayed++;
        log.record("DELAYED " + orderId + " by " + days + " day(s)");
    }

    public int shippedCount() {
        return shipped;
    }

    public int delayedCount() {
        return delayed;
    }

    public String summary() {
        return "shipped=" + shipped + " delayed=" + delayed;
    }
}
